// Split the form's photos into one item per photo, carry params + binary. Kling O1 only (720p).
const items = $input.all();
const out = [];

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const p = item.json;
  let pin = p['Motion prompt'];
  if (pin && typeof pin === 'object') { pin = pin['Motion prompt'] || Object.values(pin)[0]; }
  const prompt = (pin && String(pin).trim()) || 'Generate a video walkthrough based strictly on the provided reference photo. Move the camera as if a person is physically walking forward through the room at a natural pace — a first-person walking point of view at standing eye level. Include the subtle, organic motion of human walking: a gentle vertical bob with each step, slight natural sway from side to side, and small handheld variations, so the movement feels alive rather than a smooth mechanical slide on rails. Keep advancing forward the entire time; do not hold static, and do not move in a perfectly straight, rigid line. Keep all motion smooth enough to feel real and physically plausible, never shaky or disorienting. Preserve every object, color, material, and lighting detail exactly as it appears in the reference image, and do not add, remove, or alter anything. Do not invent or imply any unseen elements, including windows, doors, railings, openings, adjacent spaces, or light sources. If something isn’t clearly visible in the photo, it must not appear in the video. As the camera moves forward it may bring more of this same room into view, but it must stay anchored to the visual information in the reference image, and the structure of the room must not change.';
  const resolution = '720p';
  const music = String(p['Background music'] || 'No').toLowerCase() === 'yes';
  const gens = Math.max(1, Number(p['Generations per photo'] || 1));
  const model = 'kwaivgi/kling-video-o1';
  const duration = 5;

  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const meta = bin[key];
    for (let v = 1; v <= gens; v++) {
      out.push({
        json: { photo: meta.fileName || key, variant: v, apiBase: 'https://openrouter.ai/api/v1', prompt, model, duration, resolution, generate_audio: music },
        binary: { data: bin[key] }
      });
    }
  }
}

return out;

// Kling O1 image-to-video using the photo as the first frame (faithful anchor).
// Motion is driven by the prompt.
const items = $input.all();
const out = [];

for (let idx = 0; idx < items.length; idx++) {
  const it = items[idx];
  const j = it.json;
  const meta = (it.binary && it.binary.data) || {};
  const mime = meta.mimeType || 'image/jpeg';
  const buffer = await this.helpers.getBinaryDataBuffer(idx, 'data');
  const dataUri = `data:${mime};base64,${buffer.toString('base64')}`;
  out.push({ json: {
    photo: j.photo, variant: j.variant, apiBase: j.apiBase,
    requestBody: {
      model: j.model || 'kwaivgi/kling-video-o1',
      prompt: j.prompt,
      frame_images: [ { type: 'image_url', image_url: { url: dataUri }, frame_type: 'first_frame' } ],
      duration: j.duration,
      resolution: j.resolution,
      generate_audio: j.generate_audio
    }
  } });
}

return out;
